const listUserGrants = `-- name: ListUserGrants :many
SELECT offering_id, can_upload, can_download
FROM course_access
WHERE user_id = $1::uuid
  AND ($2::bool OR offering_id = ANY($3::uuid[]))
`

type ListUserGrantsParams struct {
	UserID      uuid.UUID   `json:"user_id"`
	All         bool        `json:"all"`
	OfferingIds []uuid.UUID `json:"offering_ids"`
}

type ListUserGrantsRow struct {
	OfferingID  uuid.UUID `json:"offering_id"`
	CanUpload   bool      `json:"can_upload"`
	CanDownload bool      `json:"can_download"`
}

func (q *Queries) ListUserGrants(ctx context.Context, arg ListUserGrantsParams) ([]ListUserGrantsRow, error) {
	rows, err := q.db.Query(ctx, listUserGrants, arg.UserID, arg.All, arg.OfferingIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListUserGrantsRow
	for rows.Next() {
		var i ListUserGrantsRow
		if err := rows.Scan(&i.OfferingID, &i.CanUpload, &i.CanDownload); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

