const markTimedOutSubmissionGenerated = `-- name: MarkTimedOutSubmissionGenerated :execrows
UPDATE submissions
SET status = 'generated', pdf_size_bytes = $1::bigint,
    error_count = (SELECT COUNT(*) FROM submission_issues i
                   WHERE i.submission_id = submissions.id AND i.severity = 'error' AND i.code <> 'BUILD_TIMEOUT')::int,
    completed_at = $2::timestamptz, updated_at = $2::timestamptz
WHERE submissions.id = $3 AND submissions.status = 'failed'
  AND EXISTS (SELECT 1 FROM submission_issues i WHERE i.submission_id = submissions.id AND i.code = 'BUILD_TIMEOUT')
`

type MarkTimedOutSubmissionGeneratedParams struct {
	PdfSizeBytes *int64    `json:"pdf_size_bytes"`
	At           time.Time `json:"at"`
	ID           uuid.UUID `json:"id"`
}

// Late success: a submission that was failed by the reconciler (BUILD_TIMEOUT) becomes generated.
// error_count is recalculated from the issues that remain once the timeout issue is gone.
func (q *Queries) MarkTimedOutSubmissionGenerated(ctx context.Context, arg MarkTimedOutSubmissionGeneratedParams) (int64, error) {
	result, err := q.db.Exec(ctx, markTimedOutSubmissionGenerated, arg.PdfSizeBytes, arg.At, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const nextSubmissionIssueOrder = `-- name: NextSubmissionIssueOrder :one
SELECT COALESCE(MAX(sort_order) + 1, 0)::int AS next_order FROM submission_issues WHERE submission_id = $1
`

func (q *Queries) NextSubmissionIssueOrder(ctx context.Context, submissionID uuid.UUID) (int32, error) {
	row := q.db.QueryRow(ctx, nextSubmissionIssueOrder, submissionID)
	var next_order int32
	err := row.Scan(&next_order)
	return next_order, err
}

