const timeOutStaleSubmissions = `-- name: TimeOutStaleSubmissions :many
UPDATE submissions
SET status = 'failed', error_count = 1, completed_at = $1::timestamptz, updated_at = $1::timestamptz
WHERE status = 'queued' AND created_at < $2::timestamptz
RETURNING id
`

type TimeOutStaleSubmissionsParams struct {
	At     time.Time `json:"at"`
	Cutoff time.Time `json:"cutoff"`
}

// Atomic: only rows still waiting for the worker are touched, so a result that arrives meanwhile always wins or loses cleanly.
func (q *Queries) TimeOutStaleSubmissions(ctx context.Context, arg TimeOutStaleSubmissionsParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, timeOutStaleSubmissions, arg.At, arg.Cutoff)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []uuid.UUID
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
